<script>
// ============================================================
// COIN RENDERER — 2D Canvas with full 3D simulation
// ============================================================

(function() {
'use strict';

// ---- Utility ----
function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function lerp(a, b, t) { return a + (b - a) * t; }

// ---- Render a single coin face with embossing ----
// coinCanvas: offscreen canvas for a face
// type: 'front' | 'back'
// palette: color config

function renderFace(ctx, w, h, type, palette, specX, specY) {
  const cx = w / 2, cy = h / 2;
  const R = w * 0.46;

  ctx.clearRect(0, 0, w, h);

  // Base disc
  const baseGrad = ctx.createRadialGradient(
    cx + specX * R * 0.5, cy + specY * R * 0.3, R * 0.05,
    cx, cy, R
  );
  baseGrad.addColorStop(0, palette.highlight);
  baseGrad.addColorStop(0.35, palette.mid);
  baseGrad.addColorStop(0.7, palette.base);
  baseGrad.addColorStop(1, palette.shadow);

  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, Math.PI * 2);
  ctx.fillStyle = baseGrad;
  ctx.fill();

  // Radial brushed-metal lines
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, Math.PI * 2);
  ctx.clip();
  for (let i = 0; i < 120; i++) {
    const angle = (i / 120) * Math.PI * 2;
    const alpha = 0.04 + 0.03 * Math.sin(angle * 7 + specX * 2);
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(angle) * R, cy + Math.sin(angle) * R);
    ctx.strokeStyle = `rgba(255,255,255,${alpha})`;
    ctx.lineWidth = 0.5;
    ctx.stroke();
  }
  ctx.restore();

  // Specular highlight — the key raking effect
  const specR = R * 0.7;
  const sx = cx + specX * R * 0.6;
  const sy = cy + specY * R * 0.4;
  const specGrad = ctx.createRadialGradient(sx, sy, 0, sx, sy, specR);
  specGrad.addColorStop(0, `rgba(255,255,255,${0.55 + palette.specBoost})`);
  specGrad.addColorStop(0.3, `rgba(255,255,255,${0.15 + palette.specBoost * 0.3})`);
  specGrad.addColorStop(1, 'rgba(255,255,255,0)');

  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, Math.PI * 2);
  ctx.clip();
  ctx.fillStyle = specGrad;
  ctx.fillRect(0, 0, w, h);
  ctx.restore();

  // Rim
  const rimGrad = ctx.createRadialGradient(cx, cy, R * 0.88, cx, cy, R);
  rimGrad.addColorStop(0, 'rgba(0,0,0,0)');
  rimGrad.addColorStop(0.6, `rgba(0,0,0,0.25)`);
  rimGrad.addColorStop(1, `rgba(0,0,0,0.6)`);
  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, Math.PI * 2);
  ctx.fillStyle = rimGrad;
  ctx.fill();

  // Inner border ring
  ctx.beginPath();
  ctx.arc(cx, cy, R * 0.92, 0, Math.PI * 2);
  ctx.strokeStyle = `rgba(255,255,255,0.18)`;
  ctx.lineWidth = 1.5;
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(cx, cy, R * 0.88, 0, Math.PI * 2);
  ctx.strokeStyle = `rgba(0,0,0,0.4)`;
  ctx.lineWidth = 1;
  ctx.stroke();

  if (type === 'front') {
    drawFront(ctx, cx, cy, R, palette, specX, specY);
  } else {
    drawBack(ctx, cx, cy, R, palette, specX, specY);
  }
}

function drawFront(ctx, cx, cy, R, palette, specX, specY) {
  // Central emblem: "W" monogram in relief
  const embR = R * 0.55;

  // Emblem circle background
  const eGrad = ctx.createRadialGradient(
    cx + specX * embR * 0.4, cy - embR * 0.2, embR * 0.1,
    cx, cy, embR
  );
  eGrad.addColorStop(0, palette.emblemHigh);
  eGrad.addColorStop(0.5, palette.emblemMid);
  eGrad.addColorStop(1, palette.emblemLow);

  ctx.beginPath();
  ctx.arc(cx, cy, embR, 0, Math.PI * 2);
  ctx.fillStyle = eGrad;
  ctx.fill();

  ctx.beginPath();
  ctx.arc(cx, cy, embR, 0, Math.PI * 2);
  ctx.strokeStyle = `rgba(255,255,255,0.3)`;
  ctx.lineWidth = 1;
  ctx.stroke();

  // Decorative star points around emblem
  const nPts = 8;
  for (let i = 0; i < nPts; i++) {
    const a = (i / nPts) * Math.PI * 2 - Math.PI / 2;
    const ax = cx + Math.cos(a) * (embR + R * 0.12);
    const ay = cy + Math.sin(a) * (embR + R * 0.12);
    ctx.beginPath();
    ctx.arc(ax, ay, R * 0.025, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(255,255,255,0.4)`;
    ctx.fill();
  }

  // "W" letterform — drawn as raised relief
  const relief = () => {
    // Drop shadow for depth
    ctx.shadowColor = 'rgba(0,0,0,0.7)';
    ctx.shadowBlur = 4;
    ctx.shadowOffsetX = 1.5;
    ctx.shadowOffsetY = 2;
  };

  const lW = embR * 0.9;
  const lH = embR * 0.6;
  const lx = cx - lW / 2;
  const ly = cy - lH / 2;

  relief();
  ctx.beginPath();
  // W shape
  ctx.moveTo(lx, ly);
  ctx.lineTo(lx + lW * 0.22, ly + lH);
  ctx.lineTo(lx + lW * 0.5, ly + lH * 0.45);
  ctx.lineTo(lx + lW * 0.78, ly + lH);
  ctx.lineTo(lx + lW, ly);
  ctx.lineWidth = lW * 0.1;
  ctx.strokeStyle = palette.letterColor;
  ctx.lineJoin = 'miter';
  ctx.stroke();
  ctx.shadowColor = 'transparent';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;

  // Highlight on W top edge
  ctx.beginPath();
  ctx.moveTo(lx, ly);
  ctx.lineTo(lx + lW * 0.22, ly + lH);
  ctx.lineTo(lx + lW * 0.5, ly + lH * 0.45);
  ctx.lineTo(lx + lW * 0.78, ly + lH);
  ctx.lineTo(lx + lW, ly);
  ctx.strokeStyle = `rgba(255,255,255,0.35)`;
  ctx.lineWidth = lW * 0.025;
  ctx.stroke();

  // Text ring: "WASTEDTOKEN MINT · EST. MMXIX ·"
  ctx.save();
  ctx.font = `bold ${R * 0.09}px Georgia, serif`;
  ctx.fillStyle = palette.textColor;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  const textR = R * 0.79;
  const text = 'WASTEDTOKEN  MINT  ·  EST.  MMXIX  ·';
  const chars = text.split('');
  const totalAngle = Math.PI * 2;
  for (let i = 0; i < chars.length; i++) {
    const angle = -Math.PI / 2 + (i / chars.length) * totalAngle;
    ctx.save();
    ctx.translate(cx + textR * Math.cos(angle), cy + textR * Math.sin(angle));
    ctx.rotate(angle + Math.PI / 2);
    ctx.fillStyle = palette.textColor;
    ctx.shadowColor = 'rgba(0,0,0,0.8)';
    ctx.shadowBlur = 2;
    ctx.fillText(chars[i], 0, 0);
    ctx.restore();
  }
  ctx.restore();
}

function drawBack(ctx, cx, cy, R, palette, specX, specY) {
  // Token count panel
  const panH = R * 0.65;
  const panW = R * 1.2;

  // Panel background — engraved look
  const pGrad = ctx.createLinearGradient(cx - panW/2, cy - panH/2, cx + panW/2, cy + panH/2);
  pGrad.addColorStop(0, palette.emblemLow);
  pGrad.addColorStop(0.5, palette.emblemMid);
  pGrad.addColorStop(1, palette.emblemHigh);

  ctx.fillStyle = pGrad;
  roundRect(ctx, cx - panW/2, cy - panH/2, panW, panH, 6);
  ctx.fill();

  ctx.strokeStyle = `rgba(255,255,255,0.2)`;
  ctx.lineWidth = 1;
  roundRect(ctx, cx - panW/2, cy - panH/2, panW, panH, 6);
  ctx.stroke();

  // Label lines
  ctx.save();
  ctx.shadowColor = 'rgba(0,0,0,0.9)';
  ctx.shadowBlur = 5;
  ctx.shadowOffsetY = 2;

  ctx.font = `bold ${R * 0.28}px Georgia, serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = palette.letterColor;
  ctx.fillText('10,000', cx, cy - R * 0.08);

  ctx.font = `${R * 0.1}px Georgia, serif`;
  ctx.letterSpacing = '0.2em';
  ctx.fillStyle = palette.textColor;
  ctx.fillText('TOKENS', cx, cy + R * 0.18);

  ctx.font = `${R * 0.07}px Georgia, serif`;
  ctx.fillStyle = `rgba(255,255,255,0.4)`;
  ctx.fillText('PROOF OF MEMBERSHIP', cx, cy + R * 0.3);

  ctx.restore();

  // Corner flourishes
  const fl = R * 0.15;
  [[-1,-1],[ 1,-1],[ 1, 1],[-1, 1]].forEach(([sx, sy]) => {
    const fx = cx + sx * R * 0.7;
    const fy = cy + sy * R * 0.55;
    ctx.strokeStyle = `rgba(255,255,255,0.3)`;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(fx, fy);
    ctx.lineTo(fx - sx * fl, fy);
    ctx.moveTo(fx, fy);
    ctx.lineTo(fx, fy - sy * fl);
    ctx.stroke();
  });

  // Circular text bottom
  ctx.save();
  ctx.font = `${R * 0.08}px Georgia, serif`;
  ctx.fillStyle = palette.textColor;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  const bText = 'WASTEDTOKEN MINT · GENUINE ISSUE · SERIALISED ·';
  const chars = bText.split('');
  const bR = R * 0.79;
  for (let i = 0; i < chars.length; i++) {
    const angle = Math.PI / 2 + (i / chars.length) * Math.PI * 2;
    ctx.save();
    ctx.translate(cx + bR * Math.cos(angle), cy + bR * Math.sin(angle));
    ctx.rotate(angle - Math.PI / 2);
    ctx.fillStyle = palette.textColor;
    ctx.shadowColor = 'rgba(0,0,0,0.8)';
    ctx.shadowBlur = 2;
    ctx.fillText(chars[i], 0, 0);
    ctx.restore();
  }
  ctx.restore();
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.arcTo(x + w, y, x + w, y + r, r);
  ctx.lineTo(x + w, y + h - r);
  ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
  ctx.lineTo(x + r, y + h);
  ctx.arcTo(x, y + h, x, y + h - r, r);
  ctx.lineTo(x, y + r);
  ctx.arcTo(x, y, x + r, y, r);
  ctx.closePath();
}

