// ---- 3D Coin Projection ----
// We simulate 3D by: scaleX = cos(rotY), scaleY = 1, plus perspective tilt.
// The coin rotates on Y axis AND flips on X axis in a looping animation.

function renderHeroCoin(canvas, t) {
  const W = canvas.width;
  const H = canvas.height;
  const ctx = canvas.getContext('2d');

  // t in [0,1], one full loop
  // Rotation angles
  // Y rotation (spin): full 360 per loop, plus we want 2 full Y rotations so both faces appear
  const spinY = t * Math.PI * 4; // 2 full Y spins per loop
  // X tilt (wobble flip): oscillate to show the flip
  const tiltX = Math.sin(t * Math.PI * 2) * 0.45; // gentle front-back tilt

  // Effective Y rotation (cos gives squeeze factor)
  const cosY = Math.cos(spinY);
  const sinY = Math.sin(spinY);

  // Is it showing front or back face?
  // Front when cosY >= 0, back when cosY < 0
  const showFront = cosY >= 0;
  const scaleX = Math.abs(cosY);  // coin narrows as it turns
  const cosX = Math.cos(tiltX);   // vertical squeeze from tilt
  const sinX = Math.sin(tiltX);   // vertical offset from tilt

  const palette = PALETTES.hero;

  // Specular angle moves with the rotation
  const specX = -sinY * 0.8;
  const specY = sinX * 0.6;

  ctx.clearRect(0, 0, W, H);

  // Background glow
  const bgGrad = ctx.createRadialGradient(W/2, H/2, 0, W/2, H/2, W/2);
  bgGrad.addColorStop(0, 'rgba(80,60,20,0.18)');
  bgGrad.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, W, H);

  const R = W * 0.38;
  const cx = W / 2;
  const cy = H / 2;

  // Edge reeding — only visible when coin is turning (scaleX is not 1)
  // Draw the edge as a strip visible from the side
  if (scaleX < 0.99) {
    drawEdge(ctx, cx, cy, R, cosX, sinX, scaleX, palette);
  }

  // Offscreen face
  const faceSize = Math.round(R * 2 + 4);
  const faceCanvas = document.createElement('canvas');
  faceCanvas.width = faceSize;
  faceCanvas.height = faceSize;
  const fCtx = faceCanvas.getContext('2d');
  renderFace(fCtx, faceSize, faceSize, showFront ? 'front' : 'back', palette, specX, specY);

  // Draw coin face with 3D transform
  // scaleX: horizontal squeeze (rotation around Y)
  // cosX: vertical squeeze (rotation around X / tilt)
  const drawW = R * 2 * scaleX;
  const drawH = R * 2 * Math.abs(cosX);

  // Edge thickness — visible when scaleX is small
  const edgeT = R * 0.04 * (1 - scaleX * 0.8);

  // Vertical offset from tilt
  const yOff = R * sinX * 0.15;

  ctx.save();
  ctx.translate(cx, cy + yOff);

  // Subtle drop shadow
  ctx.shadowColor = 'rgba(0,0,0,0.7)';
  ctx.shadowBlur = 30;
  ctx.shadowOffsetX = sinY * 10;
  ctx.shadowOffsetY = 15;

  if (drawW > 0.5 && drawH > 0.5) {
    ctx.drawImage(faceCanvas,
      cx - drawW / 2 - cx, -drawH / 2,
      drawW, drawH
    );
  }
  ctx.restore();
}

function drawEdge(ctx, cx, cy, R, cosX, sinX, scaleX, palette) {
  // The reeded edge — visible as the coin turns
  // Draw it as a series of ridges on the narrow side
  const edgeW = R * (1 - scaleX) * 1.0;
  if (edgeW < 1) return;

  // Which side is the edge on?
  // If coin is turning right (cosY shrinking from 1→0), edge appears on right
  // We'll draw on the correct side based on rotation direction

  ctx.save();
  ctx.translate(cx, cy);

  const h = R * 2 * Math.abs(cosX);
  const ridgeCount = 40;
  const ridgeH = h / ridgeCount;

  // Determine edge position
  const edgeDir = scaleX < 0 ? -1 : 1; // Not needed since scaleX is abs
  const ex = (edgeW / 2); // distance from center of edge strip

  // Draw the full edge strip (right side when turning)
  // Actually we draw both potential sides based on context
  // The visible edge is on the side facing toward viewer
  // Since we're doing 2D simulation: draw on the right when cos decreasing
  const edgeX = R * scaleX; // x position of the edge strip

  // Edge strip gradient
  const eGrad = ctx.createLinearGradient(edgeX, 0, edgeX + edgeW, 0);
  eGrad.addColorStop(0, palette.mid);
  eGrad.addColorStop(0.3, palette.highlight);
  eGrad.addColorStop(0.7, palette.mid);
  eGrad.addColorStop(1, palette.shadow);

  for (let i = 0; i < ridgeCount; i++) {
    const ry = -h/2 + i * ridgeH;
    const brightness = (i % 2 === 0) ? 1.0 : 0.6;
    ctx.fillStyle = i % 2 === 0 ? palette.highlight : palette.base;
    ctx.globalAlpha = 0.85;
    ctx.fillRect(edgeX, ry, edgeW, ridgeH * 0.88);
    // Ridge highlight
    ctx.fillStyle = `rgba(255,255,255,${0.3 * brightness})`;
    ctx.fillRect(edgeX, ry, edgeW * 0.3, ridgeH * 0.88);
  }

  ctx.restore();
}

// ---- Animation Loop ----
const heroCanvas = document.getElementById('coin-hero');

let animFrame = null;
let running = true;
let lastTime = 0;
let phase = 0; // 0 to 1 over the loop
const LOOP_DURATION = 4000; // ms

function step(t) {
  // t in [0,1]
  renderHeroCoin(heroCanvas, t);
}

function tick(now) {
  if (!running) return;
  if (!lastTime) lastTime = now;
  const elapsed = now - lastTime;
  lastTime = now;
  phase = (phase + elapsed / LOOP_DURATION) % 1;
  step(phase);
  animFrame = requestAnimationFrame(tick);
}

animFrame = requestAnimationFrame(tick);

